def decode(path):
 p=subprocess.run(['ffmpeg','-v','error','-i',str(path),'-map','0:v:0','-an','-f','rawvideo','-pix_fmt','rgb24','pipe:1'],capture_output=True,check=True)
 return np.frombuffer(p.stdout,np.uint8).reshape(-1,H,W,3)

