   x1,y1,x2,y2=handles if len(handles)==4 else (1/3,handles[0],2/3,handles[1]);x=3*(1-u)**2*u*x1+3*(1-u)*u*u*x2+u**3;y=3*(1-u)**2*u*y1+3*(1-u)*u*u*y2+u**3;dx=3*((1-u)**2*x1+2*(1-u)*u*(x2-x1)+u*u*(1-x2))
  else:
   x,dx=u,np.ones_like(u);y=u*u if mode=='ease_in' else 1-(1-u)**2 if mode=='ease_out' else np.where(u<.5,2*u*u,1-2*(1-u)**2) if mode=='ease_in_out' else u
