 n=4096;nodes,weights=np.polynomial.legendre.leggauss(8);grid=np.linspace(0,1,n+1);u=grid[:-1,None]+(nodes[None,:]+1)/(2*n);x,y,dx=xy(u);areas=(dx/(a+(b-a)*y)@weights)/(2*n);clocks=np.r_[0,np.cumsum(areas)];source_x=xy(grid)[0]
